const updateLoanInstallmentStatus = `-- name: UpdateLoanInstallmentStatus :one
UPDATE payroll.loan_installments
SET status = $2,
    payroll_run_id = $3,
    deducted_at = CASE WHEN $2 = 'DEDUCTED' THEN CURRENT_TIMESTAMP ELSE deducted_at END
WHERE id = $1
RETURNING id, loan_id, payroll_run_id, installment_number, due_date, amount, status, deducted_at, created_at
`

type UpdateLoanInstallmentStatusParams struct {
	ID           pgtype.UUID `json:"id"`
	Status       string      `json:"status"`
	PayrollRunID pgtype.UUID `json:"payroll_run_id"`
}

func (q *Queries) UpdateLoanInstallmentStatus(ctx context.Context, arg UpdateLoanInstallmentStatusParams) (PayrollLoanInstallments, error) {
	row := q.db.QueryRow(ctx, updateLoanInstallmentStatus, arg.ID, arg.Status, arg.PayrollRunID)
	var i PayrollLoanInstallments
	err := row.Scan(
		&i.ID,
		&i.LoanID,
		&i.PayrollRunID,
		&i.InstallmentNumber,
		&i.DueDate,
		&i.Amount,
		&i.Status,
		&i.DeductedAt,
		&i.CreatedAt,
	)
	return i, err
}

const updateLoanRemainingBalance = `-- name: UpdateLoanRemainingBalance :one
UPDATE payroll.loans
SET remaining_balance = remaining_balance - $2,
    status = CASE WHEN (remaining_balance - $2) <= 0 THEN 'PAID_OFF' ELSE status END
WHERE id = $1
RETURNING id, legal_entity_id, employee_id, loan_number, principal_amount, monthly_installment, remaining_balance, disbursement_date, status, reason, created_at
`

